// === Tab: mySketch ===
let palette = ['#fcab30', '#ff626a', '#4C1E4F', '#496ddb', '#FFC4EB']

let rects
let gap = 3 
let levelIndex = 0 
let rectsIndex = 0 
let lastTime = 0 
let lastAdd = 0
let addSpeed
let levelFinishedAdding = false 
let levelFinishedGrowing = false 
let allDone = false 
let borderRadius 
let growing = []
let dur = 1500 
let m 

function setup() {
	createCanvas(windowWidth, windowHeight)
	reset()
}

function draw() {
	translate((width - m) / 2, (height - m) / 2)
	let t = millis()
	let elapsed = t - lastTime 
	let elapsedSinceAdd = t - lastAdd 
	let fps = 1000 / addSpeed
	lastTime = t 

	if (!allDone && elapsedSinceAdd > fps) {
		lastAdd = t 
		let toDraw = round(elapsedSinceAdd / fps) 

		for (let i = 0; i < toDraw; i++) {
			if (levelFinishedAdding && levelFinishedGrowing) {
				levelIndex++

				if (levelIndex > rects.length - 1) {
					allDone = true
				}

				addSpeed *= 4
				rectsIndex = 0 
				levelFinishedAdding = false 
				levelFinishedGrowing = false
			}

			if (rectsIndex > rects[levelIndex]?.length) {
				levelFinishedAdding = true 
				continue
			}

			let rct = rects[levelIndex]?.[rectsIndex] 
			if (rct) growing.push(rct)
			rectsIndex++
		}
	}

	let almostDone = []

	growing.forEach((rct) => {
		rct.progress += elapsed / dur 
		drawRect(rct)
		if (rct.progress > 0.5) almostDone.push(rct)
	})

	growing = growing.filter((rct) => rct.progress < 1)

	if (levelFinishedAdding && almostDone.length === growing.length) levelFinishedGrowing = true
	if (allDone && growing.length === 0) noLoop()
}

function drawRect(rct) {
	let sz = rct.size - gap 
	let cx = rct.x + sz / 2
	let cy = rct.y + sz / 2 
	let scl = easeInCubic(min(rct.progress, 1)) 
	sz *= scl 
	let x = cx - sz / 2 
	let y = cy - sz / 2 

	let roundScale = rct.progress < 0.5 ? 0 : easeInQuart(map(rct.progress, 0.4, 1, 0, 1)) 
	let roundedness = max(map(roundScale, 0, 1, sz / 2, borderRadius), borderRadius)

	fill(rct.color)
	noStroke() 
	rect(x, y, sz, sz, roundedness)
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight)
	let prevM = m 
	m = max(width, height) * 0.95

	rects.forEach((rectSet) => {
		rectSet.forEach((rct) => {
			rct.size = map(rct.size, 0, prevM, 0, m)
			rct.x = map(rct.x, 0, prevM, 0, m)
			rct.y = map(rct.y, 0, prevM, 0, m)
		})
	})

	for (let li = 0; li < levelIndex; li++) {
		rects[li].forEach((rct) => drawRect(rct))
	}

	let currentLevel = rects[levelIndex] 
	if (currentLevel) {
		for (let ri = 0; ri < min(rectsIndex, currentLevel.length); ri++) {
			var rct = currentLevel[ri]
			drawRect(rct)
		}
	}


}

function reset() {
	palette = shuffle(palette)
	m = max(width, height) * 0.95
	levelIndex = 0
	rectsIndex = 0 
	lastAdd = millis()
	lastTime = millis()
	addSpeed = 3
	levelFinishedAdding = false 
	levelFinishedGrowing = false 
	allDone = false
	growing = []
	background(palette[palette.length-1])
	borderRadius = max(width, height) * 0.003
	rects = tile({
		iterations: 3,
		minSize: 10,
		palette,
		tileChance: 1,
		rects: [
			[{x: 0, y: 0, size: m, progress: 0, color: palette[0], level: 0 }]
		]
	})

}

function mouseClicked() {
	reset()
	loop()
}

function tile({ 
	iterations,
	minSize,
	rects,
	tileChance = 0.8,
	tileChanceMin = 0.5,
	currentLevel = 1
}) {
	if (iterations === 0) return rects 

	let nextRects = [] 
	let lastRects = rects[rects.length - 1]

	lastRects.forEach(({ x, y, size }) => {
		let divide = random([2, 3, 4, 5]) 
		let step = size / divide 
		if (step < minSize) return 

		if (random() < tileChance) {
			for (let yy = 0; yy < divide; yy++) {
				for (let xx = 0; xx < divide; xx++) {
					nextRects.push({
						x: x+ xx * step,
						y: y + yy * step,
						size: step,
						progress: 0,
						color: palette[currentLevel % palette.length],
						level: currentLevel
					})
				}
			}
		}
	})

	return tile({
		iterations: iterations - 1,
		rects: [...rects, shuffle(nextRects)],
		minSize,
		tileChance: Math.max(tileChance - 0.1, tileChanceMin),
		currentLevel: currentLevel + 1,
	})

}

const easeInCubic = (x) => x * x * x
const easeInQuart = (x) => x * x * x * x

